import React from 'react';
import { NavContainer, NavLogo, NavRight, NavLinks, NavLink, SocialLinks, SocialIcon } from './Navbar.styles';
import { GitHubIcon, LinkedInIcon, EmailIcon } from './Icons';
import ThemeToggle from '../ThemeToggle/ThemeToggle';

const Navbar = () => {
  return (
    <NavContainer>
      {/* 1. ThemeToggle is now the first item on the left */}
      <ThemeToggle />

      {/* 2. NavLogo is now the first item inside NavRight */}
      <NavRight>

        <NavLinks>
          <NavLink href="#home">Home</NavLink>
          <NavLink href="#projects">Projects</NavLink>
        </NavLinks>
        <SocialLinks>
          <SocialIcon href="https://github.com/darin-noronha" target="_blank" rel="noopener noreferrer"><GitHubIcon /></SocialIcon>
          <SocialIcon href="https://www.linkedin.com/in/darin-noronha/" target="_blank" rel="noopener noreferrer"><LinkedInIcon /></SocialIcon>
          <SocialIcon href="mailto:dnoronha@umich.edu"><EmailIcon /></SocialIcon>
        </SocialLinks>
      </NavRight>
    </NavContainer>
  );
};

export default Navbar;
